package me.semmmetje.banditteams.listener;

import me.semmmetje.banditteams.BanditTeams;
import me.semmmetje.banditteams.storage.Team;
import me.semmmetje.banditteams.util.Text;
import org.bukkit.Bukkit;
import org.bukkit.Material;
import org.bukkit.OfflinePlayer;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.inventory.InventoryClickEvent;
import org.bukkit.inventory.Inventory;
import org.bukkit.inventory.InventoryHolder;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.inventory.meta.SkullMeta;
import java.io.File;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.*;

public final class TeamGui implements Listener {
  private static final int[] CONTENT={10,11,12,13,14,15,16,19,20,21,22,23,24,25,28,29,30,31,32,33,34,37,38,39,40,41,42,43}; private static final DateTimeFormatter LAST_SEEN=DateTimeFormatter.ofPattern("dd MMM. uuuu",Locale.forLanguageTag("nl-NL")).withZone(ZoneId.systemDefault());
  private final BanditTeams plugin; private YamlConfiguration gui;
  public TeamGui(BanditTeams plugin){this.plugin=plugin;reload();}
  public void reload(){gui=YamlConfiguration.loadConfiguration(new File(plugin.getDataFolder(),"gui.yml"));}
  public void members(Player viewer,Team team){openMembers(viewer,team,0);}
  public void teams(Player viewer){openTeams(viewer,0);}
  public void main(Player viewer){reload();Inventory inv=base("main",Map.of(),new Holder(View.MAIN,"",0));setIfValid(inv,gui.getInt("main.finder.slot",20),item(material("main.finder.material",Material.COMPASS),gui.getString("main.finder.name","&eTeams bekijken"),gui.getStringList("main.finder.lore")));Team team=plugin.teams().teamOf(viewer.getUniqueId());String path=team==null?"main.create":"main.manage";setIfValid(inv,gui.getInt(path+".slot",24),item(material(path+".material",team==null?Material.EMERALD:Material.CLOCK),gui.getString(path+".name",team==null?"&aTeam aanmaken":"&eTeam beheren"),gui.getStringList(path+".lore")));backButton(inv,View.MAIN);viewer.openInventory(inv);}
  public void manage(Player viewer,Team team){reload();Inventory inv=base("manage",Map.of("team",team.name()),new Holder(View.MANAGE,team.name(),0));setIfValid(inv,gui.getInt("manage.settings.slot",21),item(material("manage.settings.material",Material.REPEATER),gui.getString("manage.settings.name","&eInstellingen"),gui.getStringList("manage.settings.lore")));setIfValid(inv,gui.getInt("manage.members.slot",23),item(material("manage.members.material",Material.PLAYER_HEAD),gui.getString("manage.members.name","&eLeden"),gui.getStringList("manage.members.lore")));setIfValid(inv,gui.getInt("manage.invite.slot",31),item(material("manage.invite.material",Material.EMERALD),gui.getString("manage.invite.name","&aLid uitnodigen"),gui.getStringList("manage.invite.lore")));backButton(inv,View.MANAGE);viewer.openInventory(inv);}
  public void settings(Player viewer,Team team){reload();Inventory inv=base("settings",Map.of("team",team.name()),new Holder(View.SETTINGS,team.name(),0));setIfValid(inv,gui.getInt("settings.requests.slot",21),settingItem("settings.requests",team.joinRequestsEnabled()));setIfValid(inv,gui.getInt("settings.team-chat.slot",23),settingItem("settings.team-chat",team.teamChatEnabled()));setIfValid(inv,gui.getInt("settings.friendly-fire.slot",25),settingItem("settings.friendly-fire",team.friendlyFireEnabled()));backButton(inv,View.SETTINGS);viewer.openInventory(inv);}
  private void openMembers(Player viewer,Team team,int page){reload();List<UUID> members=team.members().stream().sorted(Comparator.comparing(this::name,String.CASE_INSENSITIVE_ORDER)).toList();int pages=pages(members.size());page=Math.max(0,Math.min(page,pages-1));Inventory inv=base("members",Map.of("team",team.name()),new Holder(View.MEMBERS,team.name(),page));for(int i=0,start=page*CONTENT.length;i<CONTENT.length&&start+i<members.size();i++)setIfValid(inv,CONTENT[i],memberItem(members.get(start+i),team));setIfValid(inv,gui.getInt("members.invite.slot",45),item(material("members.invite.material",Material.EMERALD),gui.getString("members.invite.name","&aInvite Member"),gui.getStringList("members.invite.lore")));navigation(inv,View.MEMBERS,team.name(),page,pages);backButton(inv,View.MEMBERS);viewer.openInventory(inv);}
  private void openTeams(Player viewer,int page){reload();List<Team> teams=plugin.teams().allTeams().stream().sorted(Comparator.comparing(Team::name,String.CASE_INSENSITIVE_ORDER)).toList();int pages=pages(teams.size());page=Math.max(0,Math.min(page,pages-1));Inventory inv=base("teams",Map.of(),new Holder(View.TEAMS,"",page));for(int i=0,start=page*CONTENT.length;i<CONTENT.length&&start+i<teams.size();i++)setIfValid(inv,CONTENT[i],teamItem(teams.get(start+i)));String create="teams.create";setIfValid(inv,gui.getInt(create+".slot"),item(material(create+".material",Material.EMERALD),gui.getString(create+".name","Team aanmaken"),gui.getStringList(create+".lore")));navigation(inv,View.TEAMS,"",page,pages);backButton(inv,View.TEAMS);viewer.openInventory(inv);}
  private Inventory base(String section,Map<String,String> vars,Holder holder){int defaultRows=List.of("settings","main","manage").contains(section)?5:6;int rows=Math.max(1,Math.min(6,gui.getInt(section+".rows",defaultRows)));int size=rows*9;Inventory inv=Bukkit.createInventory(holder,size,Text.component(replace(gui.getString(section+".title","Teams"),vars)));Material material=material("shared.border.material",Material.BLACK_STAINED_GLASS_PANE);for(int i=0;i<size;i++){int row=i/9,column=i%9;if(row==0||row==rows-1||column==0||column==8)inv.setItem(i,item(material,gui.getString("shared.border.name"," "),List.of()));}return inv;}
  private void backButton(Inventory inv,View view){String path=view.name().toLowerCase(Locale.ROOT)+".back";int fallback=gui.getInt("shared.back.slot-"+inv.getSize(),inv.getSize()==45?40:52);int slot=gui.getInt(path+".slot",fallback);Material fallbackMaterial=material("shared.back.material",Material.ARROW);String name=gui.getString(path+".name",gui.getString("shared.back.name","&e← Go Back"));List<String> lore=gui.contains(path+".lore")?gui.getStringList(path+".lore"):gui.getStringList("shared.back.lore");setIfValid(inv,slot,item(material(path+".material",fallbackMaterial),name,lore));}
  private void setIfValid(Inventory inventory,int slot,ItemStack stack){if(slot>=0&&slot<inventory.getSize())inventory.setItem(slot,stack);}
  private void navigation(Inventory inv,View view,String team,int page,int pages){if(page>0)setNav(inv,"previous",view,team,page);setNav(inv,"page",view,team,page,Map.of("page",String.valueOf(page+1),"pages",String.valueOf(pages)));if(page<pages-1)setNav(inv,"next",view,team,page);}
  private void setNav(Inventory inv,String type,View view,String team,int page){setNav(inv,type,view,team,page,Map.of());}
  private void setNav(Inventory inv,String type,View view,String team,int page,Map<String,String> vars){String base="shared.navigation."+type;inv.setItem(gui.getInt(base+".slot"),item(material(base+".material",Material.PAPER),replace(gui.getString(base+".name"," "),vars),gui.getStringList(base+".lore").stream().map(line->replace(line,vars)).toList()));}
  private ItemStack settingItem(String key,boolean enabled){Map<String,String> vars=Map.of("status",enabled?"&aAan":"&cUit");return item(material(key+(enabled?".enabled-material":".disabled-material"),Material.LIME_DYE),replace(gui.getString(key+".name","Setting"),vars),gui.getStringList(key+".lore").stream().map(line->replace(line,vars)).toList());}
  private ItemStack memberItem(UUID id,Team team){OfflinePlayer player=Bukkit.getOfflinePlayer(id);String playerName=name(id);String role=id.equals(team.leader())?gui.getString("members.member.leader-role","&#d9a441Leider"):gui.getString("members.member.member-role","&7Lid");String status=gui.getString(player.isOnline()?"status-output.online":"status-output.offline",player.isOnline()?"&a&lONLINE":"&c&lOFFLINE");List<String> lore=new ArrayList<>(gui.getStringList("members.member.lore"));if(!id.equals(team.leader())&&plugin.teams().teamOf(team.leader())!=null)lore.add(gui.getString("members.member.kick-lore","&cKlik om dit lid uit het team te zetten."));return head(player,gui.getString("members.member.name","%player%"),lore,Map.of("player",playerName,"role",role,"online",status,"last_seen",lastSeen(player)));}
  private ItemStack teamItem(Team team){OfflinePlayer leader=Bukkit.getOfflinePlayer(team.leader());return head(leader,gui.getString("teams.team.name","%team%"),gui.getStringList("teams.team.lore"),Map.of("team",team.name(),"leader",name(team.leader()),"members",String.valueOf(team.members().size()),"max_members",String.valueOf(plugin.getConfig().getInt("max-members",10)),"join_status",joinStatus(team)));}
  private String lastSeen(OfflinePlayer player){if(player.isOnline())return gui.getString("last-seen-output.online","Now");long value=player.getLastSeen();return value<=0?gui.getString("last-seen-output.never","Never"):LAST_SEEN.format(Instant.ofEpochMilli(value));}
  private String joinStatus(Team team){if(team.members().size()>=plugin.getConfig().getInt("max-members",10))return "&cThis team is full.";if(!team.joinRequestsEnabled())return "&cJoin requests are disabled.";return "&e→ Send a join request";}
  private ItemStack head(OfflinePlayer owner,String title,List<String> lore,Map<String,String> values){ItemStack stack=new ItemStack(Material.PLAYER_HEAD);SkullMeta meta=(SkullMeta)stack.getItemMeta();meta.setOwningPlayer(owner);meta.setDisplayName(Text.color(replace(title,values)));meta.setLore(lore.stream().map(line->Text.color(replace(line,values))).toList());stack.setItemMeta(meta);return stack;}
  private ItemStack item(Material material,String title,List<String> lore){ItemStack stack=new ItemStack(material);ItemMeta meta=stack.getItemMeta();meta.setDisplayName(Text.color(title));meta.setLore(lore.stream().map(Text::color).toList());stack.setItemMeta(meta);return stack;}
  private Material material(String path,Material fallback){Material result=Material.matchMaterial(gui.getString(path,fallback.name()));return result==null?fallback:result;}
  private int pages(int count){return Math.max(1,(int)Math.ceil(count/(double)CONTENT.length));}
  private String name(UUID id){OfflinePlayer p=Bukkit.getOfflinePlayer(id);return p.getName()==null?id.toString().substring(0,8):p.getName();}
  private String replace(String text,Map<String,String> vars){for(var entry:vars.entrySet())text=text.replace("%"+entry.getKey()+"%",entry.getValue());return text;}
  @EventHandler public void click(InventoryClickEvent event){if(!(event.getInventory().getHolder() instanceof Holder holder))return;event.setCancelled(true);if(!(event.getWhoClicked() instanceof Player player))return;int slot=event.getRawSlot();if(slot<0||slot>=event.getInventory().getSize())return;if(isBackSlot(event.getInventory(),holder.view,slot)){switch(holder.view){case MAIN->player.closeInventory();case MANAGE->main(player);case MEMBERS->{Team t=find(holder.team);if(t!=null)manage(player,t);}case TEAMS->main(player);case SETTINGS->{Team t=find(holder.team);if(t!=null)manage(player,t);}}return;}if(holder.view==View.MAIN){if(slot==gui.getInt("main.finder.slot",20)){openTeams(player,0);return;}Team own=plugin.teams().teamOf(player.getUniqueId());String path=own==null?"main.create":"main.manage";if(slot==gui.getInt(path+".slot",24)){if(own==null){player.closeInventory();plugin.command().beginCreate(player);}else manage(player,own);return;}}
  if(holder.view==View.MANAGE){Team team=find(holder.team);if(team==null)return;if(slot==gui.getInt("manage.settings.slot",21)){if(team.leader().equals(player.getUniqueId()))settings(player,team);else plugin.command().send(player,"leader-only",Map.of());return;}if(slot==gui.getInt("manage.members.slot",23)){openMembers(player,team,0);return;}if(slot==gui.getInt("manage.invite.slot",31)){if(!team.leader().equals(player.getUniqueId())){plugin.command().send(player,"leader-only",Map.of());return;}player.closeInventory();plugin.command().beginInvite(player);return;}}
  if(holder.view==View.TEAMS&&slot==gui.getInt("teams.create.slot")){player.closeInventory();plugin.command().beginCreate(player);return;}if(holder.view==View.TEAMS){Team team=teamAt(holder.page,slot);if(team!=null){plugin.command().requestJoin(player,team);return;}}
  if(holder.view==View.MEMBERS){Team team=find(holder.team);if(team!=null&&slot==gui.getInt("members.invite.slot",45)){if(team.leader().equals(player.getUniqueId())){player.closeInventory();plugin.command().beginInvite(player);}else plugin.command().send(player,"leader-only",Map.of());return;}if(team!=null&&CONTENT_SLOT(slot)){UUID target=memberAt(holder.page,slot,team);if(target!=null&&!target.equals(team.leader())&&team.leader().equals(player.getUniqueId())){plugin.command().kickFromMenu(player,target);Team updated=find(holder.team);if(updated!=null)openMembers(player,updated,holder.page);}return;}}
  if(holder.view==View.SETTINGS){toggleSetting(player,holder,slot);return;}if(slot==gui.getInt("shared.navigation.previous.slot")&&holder.page>0)open(player,holder,holder.page-1);else if(slot==gui.getInt("shared.navigation.next.slot"))open(player,holder,holder.page+1);}
  private boolean isBackSlot(Inventory inv,View view,int slot){String path=view.name().toLowerCase(Locale.ROOT)+".back";return slot==gui.getInt(path+".slot",gui.getInt("shared.back.slot-"+inv.getSize(),inv.getSize()==45?40:52));}
  private void toggleSetting(Player player,Holder holder,int slot){Team team=find(holder.team);if(team==null||!team.leader().equals(player.getUniqueId())){player.closeInventory();return;}if(slot==gui.getInt("settings.requests.slot"))plugin.teams().setJoinRequests(team,!team.joinRequestsEnabled());else if(slot==gui.getInt("settings.team-chat.slot"))plugin.teams().setTeamChat(team,!team.teamChatEnabled());else if(slot==gui.getInt("settings.friendly-fire.slot"))plugin.teams().setFriendlyFire(team,!team.friendlyFireEnabled());else return;Team updated=find(team.name());if(updated!=null){settings(player,updated);plugin.command().send(player,"settings-updated",Map.of());}}
  private boolean CONTENT_SLOT(int slot){for(int value:CONTENT)if(value==slot)return true;return false;}
  private UUID memberAt(int page,int slot,Team team){for(int i=0;i<CONTENT.length;i++)if(CONTENT[i]==slot){List<UUID> members=team.members().stream().sorted(Comparator.comparing(this::name,String.CASE_INSENSITIVE_ORDER)).toList();int index=page*CONTENT.length+i;return index<members.size()?members.get(index):null;}return null;}
  private Team teamAt(int page,int slot){for(int i=0;i<CONTENT.length;i++)if(CONTENT[i]==slot){List<Team> teams=plugin.teams().allTeams().stream().sorted(Comparator.comparing(Team::name,String.CASE_INSENSITIVE_ORDER)).toList();int index=page*CONTENT.length+i;return index<teams.size()?teams.get(index):null;}return null;}
  private Team find(String name){return plugin.teams().allTeams().stream().filter(team->team.name().equalsIgnoreCase(name)).findFirst().orElse(null);}
  private void open(Player player,Holder holder,int page){if(holder.view==View.TEAMS)openTeams(player,page);else{Team team=find(holder.team);if(team!=null)openMembers(player,team,page);}}
  private enum View{MAIN,MANAGE,MEMBERS,TEAMS,SETTINGS}
  private record Holder(View view,String team,int page) implements InventoryHolder{@Override public Inventory getInventory(){return null;}}
}
